    {
      "ledger_id": "A4",
      "description": "Texted tenant Amelia Clarke about the leak and the plumber"
    },
    {
      "ledger_id": "A5",
      "description": "Logged the inbound call from the Flat 3 neighbour with safety advice given"
    },
    {
      "ledger_id": "A6",
      "description": "Escalated P1 to maintenance (ESC-106) for the key-holder entry decision"
